// Flatten one inbound email into the fields everything downstream needs.
//
// The IMAP node's "simple" format puts the headers it does not promote to the
// top level into `metadata`, lower-cased. Message-ID, In-Reply-To and
// References live there, and they are how a reply finds its thread.

// Not $input: this node sits after the prompt and schema reads, so its input
// is the schema file. The email is the trigger's output and has to be named.
//
// Every email, not the first: one IMAP delivery can carry several, and they
// are all marked read on fetch. Reading only .first() dropped the rest, so a
// reply or a "stop" that arrived with another mail was never seen (audit,
// 2026-09-29). The nodes after this run once per item.
return $('Email Received').all().map((item) => {
const e = item.json;
const meta = e.metadata || {};
const h = (name) => (meta[name] ?? meta[name.toLowerCase()] ?? '').toString().trim();

const fromRaw = (e.from || '').toString();
const angle = fromRaw.match(/<([^>]+)>/);
const fromEmail = (angle ? angle[1] : fromRaw).trim().toLowerCase();

// Thread keys, newest reference last. A reply carries In-Reply-To; a reply to a
// reply carries the whole chain in References, and our Message-ID may be
// anywhere in it.
const refs = h('references').split(/\s+/).filter(Boolean);
const inReplyTo = h('in-reply-to');
const threadKeys = [...new Set([inReplyTo, ...refs].filter(Boolean))];

// Auto-replies are filtered before any model sees them. These headers are what
// well-behaved autoresponders set; docs/workflows.md asks for the filter and
// the classifier prompt would otherwise spend a call to answer OUT_OF_SCOPE.
const autoSubmitted = h('auto-submitted').toLowerCase();
const precedence = h('precedence').toLowerCase();
const isAutoReply =
  (autoSubmitted !== '' && autoSubmitted !== 'no') ||
  ['bulk', 'list', 'junk'].includes(precedence) ||
  h('x-autoreply') !== '' ||
  h('x-autorespond') !== '' ||
  h('x-auto-response-suppress') !== '' ||
  /^(auto(matic)?[- ]?reply|out of office|automatische)/i.test((e.subject || '').toString());

// A bounce is not a reply either, and it names a different sender than the
// person we wrote to.
const isBounce =
  /^(mailer-daemon|postmaster)@/i.test(fromEmail) ||
  h('x-failed-recipients') !== '' ||
  /^(undeliverable|delivery status notification|returned mail|mail delivery failed)/i
    .test((e.subject || '').toString());

const body = ((e.textPlain || '') || (e.textHtml || '').replace(/<[^>]+>/g, ' '))
  .replace(/\r\n/g, '\n')
  .trim();

// Who bounced. The DSN comes from the mailer daemon, so the sender says
// nothing; the failed address is in X-Failed-Recipients or in the report's
// Final-Recipient / Original-Recipient lines, or in Gmail's own wording. A 4.x.x
// status is a temporary failure and does not suppress; anything else does.
const bouncedEmails = !isBounce ? [] : [...new Set([
  ...h('x-failed-recipients').split(/[,\s]+/),
  ...[...body.matchAll(/(?:final|original)-recipient:\s*rfc822;\s*<?([^\s>]+@[^\s>]+)>?/gi)].map((m) => m[1]),
  ...[...body.matchAll(/(?:wasn't|was not|couldn't be|could not be) delivered to\s+<?([^\s>]+@[^\s>,]+?)>?[\s,.]/gi)].map((m) => m[1]),
].map((a) => String(a || '').trim().toLowerCase()).filter((a) => /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(a)))];
const dsnStatus = (body.match(/^status:\s*([245]\.\d{1,3}\.\d{1,3})/im) || [])[1] || null;

return {
  json: {
    external_message_id: h('message-id'),
    from_email: fromEmail,
    subject: (e.subject || '').toString().slice(0, 500),
    body: body.slice(0, 20000),
    thread_keys: threadKeys,
    is_auto_reply: isAutoReply,
    is_bounce: isBounce,
    bounced_emails: bouncedEmails,
    bounce_hard: isBounce && !(dsnStatus && dsnStatus.startsWith('4.')),
    dsn_status: dsnStatus,
    received_at: (e.date || '').toString(),
  },
  pairedItem: { item: 0 },
};
});

// Assemble the classification request. The prompt and the output contract are
// read from disk so prompts/classifier.md and agents/classifier/schema.json
// stay the only place either is defined.

function fencedBlockUnder(markdown, heading) {
  const section = markdown.split(new RegExp('^##\\s+' + heading + '\\s*$', 'm'))[1];
  if (!section) throw new Error('prompts/classifier.md: no "## ' + heading + '" heading');
  const fence = section.match(/```[a-z]*\n([\s\S]*?)\n```/);
  if (!fence) throw new Error('prompts/classifier.md: no fenced block under "## ' + heading + '"');
  return fence[1].trim();
}

const doc = $('Prompt To Text').first().json.data;
const systemPrompt = fencedBlockUnder(doc, 'System prompt');

// The categories table and the UNSUBSCRIBE rules are instruction, not prose:
// the precedence list in the system prompt is useless without the definitions.
const catStart = doc.indexOf('## Categories');
const exStart = doc.indexOf('## Examples');
if (catStart === -1 || exStart === -1) {
  throw new Error('prompts/classifier.md: could not locate Categories or Examples');
}
const guidance = doc.slice(catStart, exStart).trim();

const schema = JSON.parse($('Schema To Text').first().json.data);
delete schema.$schema; delete schema.$id; delete schema.title;

const inbound = $('Prepare Inbound').item.json;
const thread = $('Match Thread').item.json;

const brief = [
  'The consultant wrote to ' + (thread.full_name || 'someone') +
    ' at ' + (thread.company_name || 'a company') + '.',
  '',
  'REPLY FROM: ' + inbound.from_email,
  'SUBJECT: ' + inbound.subject,
  '',
  'BODY:',
  inbound.body,
].join('\n');

return {
  json: {
    model: $env.OLLAMA_CLASSIFIER_MODEL || $env.OLLAMA_MODEL || 'llama3.1:8b',
    messages: [
      { role: 'system', content: systemPrompt + '\n\n' + guidance },
      { role: 'user', content: brief },
    ],
    format: schema,
    stream: false,
    options: { temperature: 0 },
  },
};

// Parse the model's answer and decide whether it is usable.
//
// The schema is checked here rather than trusted, and the two flags that carry
// consequences - requested_stop and human_required - are coerced to booleans
// rather than read loosely: a string "false" is true in JavaScript, and that
// particular bug would suppress nobody or suppress everybody.

// Set by the builder, not detected: a Code node cannot read its own name,
// and $node.name throws "Referenced node doesn't exist".
const ESCALATED = false;
const raw = $input.item.json;
const content = raw?.message?.content ?? raw?.choices?.[0]?.message?.content ?? '';

let out = null;
try {
  out = typeof content === 'string' ? JSON.parse(content) : content;
} catch (err) {
  out = null;
}

const CATEGORIES = ['POSITIVE','QUESTION','PRICE','NOT_NOW','NEGATIVE','REFERRAL','UNSUBSCRIBE','OUT_OF_SCOPE'];
const asBool = (v) => v === true || v === 'true' || v === 1;

const problems = [];
if (!out || typeof out !== 'object') problems.push('response was not JSON');
else {
  if (!CATEGORIES.includes(out.category)) problems.push('category "' + out.category + '" is not one of the eight');
  const c = Number(out.confidence);
  if (!Number.isFinite(c) || c < 0 || c > 1) problems.push('confidence is not a number in 0..1');
  if (typeof out.reason !== 'string' || out.reason.trim() === '') problems.push('reason is empty');
}

// A response we cannot read is not a licence to guess. It is treated as the
// least confident possible answer, which routes it to a human.
let classification = problems.length ? {
  category: 'OUT_OF_SCOPE',
  confidence: 0,
  reason: 'unusable model response: ' + problems.join('; '),
  requested_stop: false,
  human_required: true,
} : {
  category: out.category,
  confidence: Number(out.confidence),
  reason: String(out.reason).slice(0, 300),
  requested_stop: asBool(out.requested_stop),
  human_required: asBool(out.human_required),
  mentioned_timeline: out.mentioned_timeline ? String(out.mentioned_timeline).slice(0, 120) : null,
  referred_to: out.referred_to ? String(out.referred_to).slice(0, 200) : null,
};

const inbound = $('Prepare Inbound').item.json;
const thread = $('Match Thread').item.json;

// A deterministic opt-out check, in every language outreach is written in.
// The model decides the category; this can only ever turn a reply INTO an
// opt-out, never out of one, because missing a "stop" is the one mistake here
// that cannot be undone (prompts/classifier.md). It reads only the new part of
// the reply: the quoted original carries our own signature, which says
// Reply "stop", and a positive reply quoting it must not suppress anyone.
function newPart(text) {
  const lines = String(text || '').split('\n');
  const out = [];
  for (const line of lines) {
    if (/^\s*>/.test(line)) break;
    if (/^\s*(on .+wrote:|dana .+(je )?napisa|.+ je napisao:|.+ je napisala:|am .+schrieb|-{2,}\s*original message|-{5,}|from:\s|od:\s|šalje:|poslato:|sent:\s)/i.test(line)) break;
    if (/^--\s*$/.test(line)) break;
    out.push(line);
  }
  return out.join('\n');
}
const OPT_OUT = [
  // English
  /\bunsubscribe\b/i, /\bremove me\b/i, /\btake me off\b/i, /\bopt[ -]?out\b/i,
  /\bstop (e-?mailing|contacting|writing|messaging)\b/i, /\b(do not|don'?t) (contact|e-?mail|write to) me\b/i,
  // Serbian, Croatian, Bosnian, Montenegrin (Latin)
  /\bodjav/i, /\bskinite me\b/i, /\b(iz)?bri[sš]ite me\b/i, /\bobri[sš]ite me\b/i, /\buklonite me\b/i,
  /\bne (želim|zelim) (vi[sš]e )?(da (mi )?(se javljate|pi[sš]ete|[sš]aljete)|poruke|mailove|mejlove|e-?mailove)\b/i,
  /\bne (šaljite|saljite|kontaktirajte|pi[sš]ite)\b/i, /\bnemojte (mi )?(vi[sš]e )?(slati|pisati|se javljati)\b/i,
  /\bprestanite (da )?(mi )?([sš]aljete|pi[sš]ete|se javljate)\b/i,
  // Serbian and Macedonian (Cyrillic)
  /одјав/i, /скините ме/i, /избришите ме/i, /не шаљите/i, /не контактирајте/i, /немојте (ми )?(више )?(слати|писати)/i,
  /не праќајте/i, /отстранете ме/i,
  // Slovenian
  /\bne po[sš]iljajte\b/i, /\bodstranite me\b/i,
  // Anywhere: a data-protection request is an opt-out (prompts/classifier.md)
  /\bgdpr\b/i,
];
const BARE_STOP = /^\s*(stop|стоп)\s*[.!]*\s*$/im;
function optOutPhrase(text) {
  const t = newPart(text);
  if (BARE_STOP.test(t)) return 'stop';
  for (const re of OPT_OUT) { const m = t.match(re); if (m) return m[0]; }
  return null;
}

const phrase = optOutPhrase(inbound.body);
if (phrase && !(classification.category === 'UNSUBSCRIBE' || classification.requested_stop)) {
  classification.reason = ('opt-out phrase "' + phrase + '" in the reply; the model said ' +
    classification.category + ': ' + classification.reason).slice(0, 300);
  classification.category = 'UNSUBSCRIBE';
  classification.requested_stop = true;
  classification.confidence = 1;
}

return {
  json: {
    ...inbound,
    ...thread,
    classification,
    escalated: ESCALATED,
    model: raw?.model || null,
    problems,
  },
};

