// The reply draft request (prompts/reply-draft.md). The draft goes to Telegram
// for the operator to copy into their mail client; nothing here sends anything.

const doc = $json.data;
const section = doc.split(/^##\s+System prompt\s*$/m)[1];
const fence = section && section.match(/```[a-z]*\n([\s\S]*?)\n```/);
if (!fence) throw new Error('prompts/reply-draft.md: no fenced block under "## System prompt"');
const systemPrompt = fence[1].trim();

const ctx = $('Reply Context').item.json;
const applied = $('Apply Classification').item.json;

const brief = [
  'COMPANY: ' + ctx.company_name + ' (' + ctx.domain + '), country ' + (ctx.country || 'unknown') +
    ', segment ' + (ctx.segment || 'none'),
  'WHAT RESEARCH FOUND: ' + (ctx.research_summary || 'nothing recorded'),
  '',
  'WHAT URO\u0160 SENT',
  ...(ctx.sent || []).map((m) => '--- ' + String(m.sent_at).slice(0, 10) + ', subject: ' + m.subject + '\n' + m.body),
  '',
  'THE THREAD SO FAR (oldest first)',
  ...(ctx.thread || []).map((m) => '--- ' + m.direction + ', ' + String(m.at).slice(0, 16) + '\n' + m.body),
  '',
  'Their latest message was classified ' + applied.category + '.',
  'Write the reply body to their latest message.',
].join('\n');

return {
  json: {
    model: $env.OLLAMA_REPLY_MODEL || 'qwen3.6:27b',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: brief },
    ],
    stream: false,
    think: false,
    options: { temperature: 0.3 },
  },
};
